const srcDir = 'e:/KTS/123/.gemini_brain_backup';
const targetDir = 'C:/Users/ckgam/.gemini/antigravity/brain/724a6bcd-bcc3-4ca2-973c-d3661f6678bd';

function copyRecursive(src, dest) {
  if (!fs.existsSync(src)) return;
  const stat = fs.statSync(src);
  if (stat.isDirectory()) {
    if (!fs.existsSync(dest)) fs.mkdirSync(dest, { recursive: true });
    for (const file of fs.readdirSync(src)) {
      if (file === '.system_generated') continue; // keep system generated logs separate to not corrupt current session
      copyRecursive(path.join(src, file), path.join(dest, file));
    }
  } else {
    fs.copyFileSync(src, dest);
    console.log('Copied:', path.relative(srcDir, src));
  }
}

copyRecursive(srcDir, targetDir);
console.log('Brain artifacts restored successfully to current conversation.');
